def collapse_ints(nums: list[int]) -> str:
    """See SPEC.md."""
    distinct = sorted(set(nums))
    parts: list[str] = []
    i = 0
    n = len(distinct)
    while i < n:
        j = i
        while j + 1 < n and distinct[j + 1] == distinct[j] + 1:
            j += 1
        run = distinct[i : j + 1]
        if len(run) >= 4:
            first, last = run[0], run[-1]
            fs = f"({first})" if first < 0 else str(first)
            ls = f"({last})" if last < 0 else str(last)
            parts.append(fs + "-" + ls)
        else:
            for x in run:
                parts.append(str(x))
        i = j + 1
    return ",".join(parts)

